"""
Abstract Base classes for all single-modality DataReaders and Writers
"""

import os.path
import re
import h5py
import json

import numpy as np
import pandas as pd
from pandas import DataFrame
from abc import ABC, abstractmethod
from datetime import datetime

from common.utils import get_version
from common.utils.time import get_sample_intv, timestamp_to_unix, align_timestamps, unix_to_timestamps, undupe_time, get_sample_freq
from common.utils.slicing import array_squash, array_unsquash
from server.settings import SETTINGS_FILENAME


def file_start_end(file_path):
    """Return the start and end timestamps of the file as per the filename"""
    group = re.search('_([0-9]{13})_([0-9]{13})', file_path)
    # TODO: would be good to use timestamps instead of raw POSIX time
    return [round(float(group[1][:10])), round(float(group[2][:10]))]


class DataLoadError(Exception):
    pass


class DataReader(ABC):
    """
    Base class for common HDF5 file reader functions



    This class cannot be used directly and must be subclassed for each modality of data stored in the HDF5 file

    The attributes `group_name` `dataset_name` and `time_name` specify where in the data file to find the data
    The
    """

    def __init__(self, location):
        """
        Specify the file. Data loading should occur in later functions, even in subclasses.

        :param location: Path to the location of the HDF5 file where the relevant data is stored
        """
        self.file_location = location
        self._attributes = None
        self.data_slice = None
        self.time_slice = None
        self._computed_sample_freq = None
        self.selected_dim_labels = None
        self._start_time = None
        self._end_time = None
        self._sample_freq = None
        self._soft_write = False

    def open_file(self):
        return h5py.File(self.file_location)

    @property
    def attributes(self):
        if self._attributes is None:
            with self.open_file() as file:
                self._attributes = {}
                self._attributes.update(file[self.group_name].attrs)
                self._attributes.update(file[self.group_name][self.dataset_name].attrs)
        return self._attributes

    @property
    @abstractmethod
    def group_name(self):
        """Name of the group that data of this type is stored in"""
        return None

    @property
    @abstractmethod
    def dataset_name(self):
        """Base name of the dataset (in the group) to store the raw data in"""
        return None

    @property
    def dim_names(self):
        """Names of each dimension in the dataset"""
        return json.loads(self.attributes['dim_names'])

    @property
    def dim_labels(self):
        """Names of each coordinate for each dimension in the dataset"""
        return json.loads(self.attributes['dim_labels'])

    @property
    def start(self):
        """Datetime of the start of this data stream"""
        return self.attributes["start_time"]

    @property
    def end(self):
        """Datetime of the end of this data stream"""
        return self.attributes["end_time"]

    @property
    def sample_freq(self):
        """Median observed sampling frequency for this stream"""
        if(self._computed_sample_freq is None):
            return get_sample_freq(self.timestamps[:100])
        else:
            return self._computed_sample_freq

    def time_to_index(self, time):
        """Convert a Unix timestamp to nearest index (aka num samples after start of recording)"""
        return round((time - self.start) * self.sample_freq)

    def all_time(self):
        return slice(None)

    def select_time(self, min_time, max_time, type):
        """
        Select a range of times within the neural data, using several time measures:
            - Time in seconds since the start of the recording
            - A Unix timestamp
            - A pandas datetime
            - A Pandas timedelta


            # TODO: must be unix for now, implement automatic detection & conversion

        :param min_time:
            Represents time where selection starts
            Throws ValueError if time is out of bounds or min time is larger than max time
        :param max_time:
            Represents time where selection ends
            Throws ValueError if time is out of bounds or max time is smaller than min time
        :param type
            Defines timestamp type. Should be either 'since_start', 'unix', 'datetime', or 'timedelta'
            Throws ValueError if not one of the above types
        :return:
        """
        if(min_time > max_time):
            raise ValueError("Min time is larger than max time")
        if(type == 'since_start'):
            start_i = min_time/self.sample_freq
            end_i = max_time/self.sample_freq
        elif(type == 'unix'):
            start_i = self.time_to_index(min_time)
            end_i = self.time_to_index(max_time) + 1
        elif(type == 'datetime'):
            # Convert pd.dateTime to unix epoch
            min_val = (min_time - pd.Timestamp("1970-01-01")) // pd.Timedelta(np.timedelta64(1, "ms"))
            max_val = (max_time - pd.Timestamp("1970-01-01")) // pd.Timedelta(np.timedelta64(1, "ms"))
            if(min_val < self.start or max_val > self.end):
                raise ValueError("Datetime out of bounds")
            start_i = min_val/self.sample_freq
            end_i = max_val/self.sample_freq
        elif(type == 'timedelta'):
            min_val = min_time.total_seconds()
            max_val = max_time.total_seconds()
            if(min_val < self.start or max_val > self.end):
                raise ValueError("Timedelta out of bounds")
            start_i = min_val/self.sample_freq
            end_i = max_val/self.sample_freq
        else:
            raise ValueError("Unsupported type requested")


        self.time_slice = slice(start_i, end_i)

    def select_data(self, selector):
        """
        Select which columns to draw data from
        @:param selector: A tuple containing input column names as lists. If column name is an empty string
        all columns from that label will be added.
        """
        columns = []
        selector_num = 0
        for i in range(len(self.dim_names)):
            col_labels = self.dim_labels[i]
            # If column label is not included (at end of selector) or if selector specifies an empty
            # string, add all column labels for current dim name
            if(selector_num >= len(selector) or selector[selector_num] == ''):
                columns.append(col_labels)
                selector_num += 1
            elif(self.dim_labels[i] != None):
                cur_selector_element = selector[selector_num]
                #If input selector element is a single element, convert it to a list
                if(type(cur_selector_element) is not list):
                    cur_selector_element = [cur_selector_element]
                select_intersection = list(filter(lambda x: x in col_labels, cur_selector_element))
                if(select_intersection != None):
                    columns.append(select_intersection)
                    selector_num += 1
                else:
                    break
            else:
                columns.append(None)
        self.selected_dim_labels = columns




    def all_data(self, time_slice):
        """"""
        return time_slice, slice(None)

    def read(self):
        """
        Return the subset of the data pointed to by the current slices as a pandas DataFrame

        :return:
        """
        time_slice = self.time_slice if self.time_slice else self.all_time()
        data_slice = self.data_slice if self.data_slice else self.all_data(time_slice)

        with self.open_file() as datafile:
            group = datafile[self.group_name]

            timestamps = group[self.time_name][time_slice]
            data = group[self.dataset_name][data_slice]

            dataset = self.to_dataframe(timestamps, data)
            dataset.attrs = self.attributes

        return dataset

    def to_dataframe(self, timestamps, data):
        """
        Convert the passed timestamps and data to a pd.DataFrame as specified by the attributes

        Flattens the high-dimensional data into a 2d time-by-timeseries array. Columns are set to a human-readable
            MultiIndex based on the labels specified in self.dim_labels and self.dim_names, and the timestamps
            are set as the row index.

        :params timestamps: Iterable of all the timestamps for each data point
        :params data: n-d array of data measurements
        :returns: pandas DataFrame of all the passed data
        """
        times = unix_to_timestamps(timestamps, units='s')
        flat, row_shape = array_squash(data)

        # Prepare the column labels based on the dimension labels saved in the file
        if(self.selected_dim_labels):
            col_names = self.selected_dim_labels[1:]
        else:
            col_names = self.dim_labels[1:]
        n_cols = np.prod(row_shape)
        multi_label = []
        for i, name in enumerate(col_names):
            ext_factor = np.prod([len(ls) for ls in col_names[i+1:]])
            if not ext_factor:
                ext_factor = 1
            extended = []
            for label in col_names[i]:
                extended.extend([label] * round(ext_factor))
            multi_label.append(extended * round(n_cols/len(extended)))

        if len(multi_label) > 1:
            col_names = pd.MultiIndex.from_tuples(
                zip(*multi_label),
                names=self.dim_names[1:]
            )
        else:
            col_names = multi_label[0]

        return pd.DataFrame.from_records(flat, index=times, columns=col_names)


class DataWriter(DataReader, ABC):
    """Base class for common HDF5 file writer functions"""

    def __init__(self, location):
        """
        Point the writer at the correct destination

        :param location: full path to the file to write into
        """
        self._timestamps = None
        self._data = None

        #: Storage of stream-specific attributes for when multiple data streams are present in group
        self.stream_attributes = {}

        super(DataWriter, self).__init__(location)

    @classmethod
    def from_ready(cls, output, timestamps, data, attributes):
        """Create a writer from already-prepared timestamps, data and attributes"""
        new = cls(output)
        new._timestamps = timestamps
        new._data = data
        new._attributes = attributes
        return new

    @staticmethod
    def stack_attrs(writers):
        """
        Combine the attributes from all writers in the stack in an intelligent way
           - Some attrs, like end_time, have specific meaningful behaviour (handle these outside this function)
           - Some attrs are the same for all elements of stack, so these can be saved as is
           - Some attrs change in a meaningful way, and we need to save all of these values

        :param writers: time-ordered iterable initialized and loaded Writer objects of the same Type
        :returns: a dictionary containing stacked parameters for all writers
        """
        attributes = writers[0].attributes
        changing_attrs = []
        for key in attributes.keys():
            for w in writers:
                try:
                    if w.attributes[key] != attributes[key]:
                        changing_attrs.append(key)
                        break   # Already know this attr changes, don't need to keep checking
                except KeyError:
                    # Writers when chest data doesn't exist will have very limited attributes
                    pass

        for key in changing_attrs:
            multi_value = []
            for w in writers:
                try:
                    value = w.attributes[key]
                except KeyError:
                    # Writers when chest data doesn't exist will have very limited attributes
                    value = None
                multi_value.append(value)
            attributes[key] = multi_value
        return attributes

    @classmethod
    def from_stack(cls, writers):
        """
        Concatenate a time-ordered sequence of data writers of the same type together

        This function is intended to handle the case where multiple recordings are performed on a single day and
        need to be stored in the same file. The data from all the writers is concatenated, in order and used to
        create a new writer that contains all the data.

        :param writers: time-ordered iterable initialized and loaded Writer objects of the same type as this subclass
        :returns: A single Writer object of the type of the subclass
        """

        old_time = np.concatenate([w._timestamps for w in writers], axis=0)
        old_values = np.concatenate([w._data for w in writers], axis=0)
        squashed, row_shape = array_squash(old_values)
        old_data = pd.DataFrame.from_records(squashed, index=old_time)

        # Ensure that time is filled for all times, regardless of whether there is data there
        unduped = undupe_time(old_data, index_name='index')
        new_data = unduped.resample(f'{get_sample_intv(old_time).total_seconds()}S').nearest(limit=1)

        # Combine the attributes from all writers in the stack in an intelligent way
        attributes = cls.stack_attrs(writers)

        ready_data = array_unsquash(new_data.values, row_shape)
        return cls.from_ready(writers[0].file_location, new_data.index, ready_data, attributes)

    def open_file(self, mode='r+'):
        """Return an open HDF5 file corresponding to this reader's file location"""
        if not os.path.exists(self.file_location):
            mode = 'w'
        return h5py.File(self.file_location, mode)

    @abstractmethod
    def prep_data(self):
        """
        Format and return both the timestamps and the main dataset ready for writing

        This is a stub, and must be overwritten by subclasses. No need to make a super(...) call
        """
        timestamps, data = np.array, DataFrame()
        undupe_time(data)  # Remember to remove duplicate times from the OpenMind data
        return timestamps, data

    @abstractmethod
    def prep_attributes(self):
        """
        Format and return both the timestamps and the main dataset ready for writing

        Be sure to call super(...) in your implementation to include these base attributes
        """
        server_git = get_version(package_name='server')
        common_git = get_version(data_net_common=True, package_name='common')

        base_attrs = {
            'date generated': datetime.now().strftime('%Y-%m-%d %H:%M'),
            'server git repo': server_git[0],
            'server git commit': server_git[1],
            'common git repo': common_git[0],
            'common git commit': common_git[1],
            'dimension names': self.dim_names,
            'start_time': self._timestamps[0].timestamp(),
            'end_time': self._timestamps[-1].timestamp(),
            'dim_names': json.dumps(self.dim_names),
            'dim_labels': json.dumps(self.dim_labels)
        }
        return base_attrs

    def load(self):
        """Convenience function to format all the data and metadata ready for writing"""

        self._timestamps, self._data = self.prep_data()
        self._attributes = self.prep_attributes()

    def write(self):
        """
        Write the loaded data out to the target HDF5 file.

        The data and timestamps to write must be stored in self._data and self._timestamps respectively. The, the save
            location, group name, and dataset names are dictated by self.file_location, self.group_name and
            self.dataset_name respectively.

        If self.soft_write is True: If a compatible set of timestamps exists, do not attempt to overwrite it
            For some data streams, multiple writers can use the same set of timestamps, no need to re-write

        """

        if self._timestamps is None or self._data is None or self._attributes is None:
            raise DataLoadError('Data was not properly loaded! Aborting write')

        with self.open_file() as f:
            # TODO: setup chunking
            # TODO: think about over-writing old data

            try:
                out_group = f.create_group(self.group_name)
            except ValueError:
                # Allow writing into existing groups
                out_group = f[self.group_name]

            for k, v in self._attributes.items():
                try:
                    out_group.attrs[k] = v
                except TypeError:
                    out_group.attrs[k] = str(v)

            # Allow duplicate times if soft_write is set
            if self._soft_write and self.time_name in list(out_group.keys()):
                pass    # Timestamps already exist, don't need to write
            else:
                out_group.create_dataset(self.time_name, data=timestamp_to_unix(self._timestamps))
            # Always write data, this must be unique
            try:
                data_out = out_group.create_dataset(self.dataset_name, data=self._data)
            except TypeError:
                data_out = out_group.create_dataset(self.dataset_name, data=self._data.astype('S'))
            for k, v in self.stream_attributes.items():
                try:
                    data_out.attrs[k] = v
                except TypeError:
                    data_out.attrs[k] = json.dumps(v)


class RCSBaseWriter(DataWriter, ABC):
    """
    Common subclass of DataWriter for all RC+S (particularly OpenMind output) derived data modalities

    These modalities share a common need for and format of settings files. Additionally the data for the left and
    right devices from a single time is always accessed and stacked in the same way.
    """

    def __init__(self, target):
        self.left_data = None
        self.right_data = None
        self.left_settings = None
        self.right_settings = None

        self.left_offset = None
        self.right_offset = None

        self.left_source = None
        self.right_source = None

        super(RCSBaseWriter, self).__init__(target)

    @classmethod
    def from_sources(cls, left_source, right_source, target_loc, filename):
        """Instantiate a writer from the raw source files whose locations are provided"""
        base = cls(target_loc)

        if filename is not None:
            base.left_data = undupe_time(pd.read_csv(os.path.join(left_source, filename), index_col=['timestamp']))
            base.right_data = undupe_time(pd.read_csv(os.path.join(right_source, filename), index_col=['timestamp']))

        base.left_settings = base.get_settings(left_source)
        base.right_settings = base.get_settings(right_source)

        base.left_source = left_source
        base.right_source = right_source

        return base

    @staticmethod
    def get_settings(base_name):
        """Determine the name of settings file that corresponds to this neural data file"""
        with open(os.path.join(base_name, SETTINGS_FILENAME)) as f:
            settings = json.load(f)
        return settings

    def prep_data(self):
        """Combine the left and right data sources into a single data stream"""
        l_offset = self.left_offset if self.left_offset else pd.Timedelta(seconds=0)
        r_offset = self.right_offset if self.right_offset else pd.Timedelta(seconds=0)

        self.left_data.index = unix_to_timestamps(self.left_data.index) + l_offset
        self.right_data.index = unix_to_timestamps(self.right_data.index) + r_offset
        new_time, left_aligned, right_aligned = align_timestamps(self.left_data, self.right_data)
        shape = (-1, *[len(self.dim_labels[i]) for i in range(2, len(self.dim_labels))])
        l_ready = np.reshape(left_aligned.values, shape)
        r_ready = np.reshape(right_aligned.values, shape)

        stacked_data = np.stack([l_ready, r_ready], axis=1)
        if stacked_data.shape[0] != new_time.shape[0]:
            raise IndexError(f'Timestamps and data are of different lengths! '
                             f'({stacked_data.shape[0]} vs {new_time.shape[0]})')

        return new_time, stacked_data

    def collect_alignments(self, left_side=0, right_side=0, cross_side=0):
        """
        Collect all necessary timestamps to bring neural time in line with right wristwatch time

        :param left_side: difference in time between the left RC+S and left wristwatch timestamps
        :param right_side: difference in time between the right RC+S and right wristwatch timestamps
        :param cross_side: difference in time between the left and right RC+S times
        """
        self.left_offset = left_side + cross_side
        self.right_offset = right_side